// Code node: split documents into passages and build Gemini embedding batches (Run Once for All Items)
// Input items: { kb, docId, title, text } for knowledge-base docs, or { kb:'doc', token, name, pages:[...] } for uploads.
const MODEL = 'models/gemini-embedding-001';
const DIMS = 768;
const MAX_CHARS = 1000;
const MAX_CHARS_PDF = 700;
const MAX_UPLOAD_PASSAGES = 60;
const BATCH = 90;

const clean = (s) => String(s || '').replace(/\r/g, '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();

// Break a long block into pieces of up to MAX_CHARS, preferring paragraph and sentence boundaries.
// Numbered headings such as "4. Timeline" always start a new passage.
function pieces(text, MAX = MAX_CHARS) {
  const out = [];
  let cur = '';
  const parts = text.split(/\n\n+|\n(?=- )|\n(?=\d{1,2}\.\s+[A-Z])/);
  for (let p of parts) {
    p = p.trim();
    if (!p) continue;
    if (/^\d{1,2}\.\s+[A-Z]/.test(p) && cur) { out.push(cur); cur = ''; }
    while (p.length > MAX) {
      let cut = p.lastIndexOf('. ', MAX);
      if (cut < MAX * 0.5) cut = p.lastIndexOf(' ', MAX);
      if (cut < 1) cut = MAX;
      if (cur) { out.push(cur); cur = ''; }
      out.push(p.slice(0, cut + 1).trim());
      p = p.slice(cut + 1).trim();
    }
    if ((cur + '\n' + p).length > MAX && cur) { out.push(cur); cur = p; }
    else cur = cur ? cur + '\n' + p : p;
  }
  if (cur) out.push(cur);
  return out;
}

const passages = [];
let meta = {};
for (const { json: d } of $input.all()) {
  if (d.kb === 'doc') {
    // Uploaded PDF: one entry per page (or one block of text), chunked with the page number kept.
    meta = { mode: 'upload', token: d.token, name: d.name, pageCount: d.pageCount };
    const pages = Array.isArray(d.pages) ? d.pages : [];
    pages.forEach((pg, i) => {
      for (const t of pieces(clean(pg), MAX_CHARS_PDF)) {
        if (t.length < 40) continue;
        passages.push({ kb: 'doc', docId: d.token, title: d.name, section: /^\d{1,2}\.\s+[A-Z]/.test(t) ? `Page ${i + 1} · ${t.split('\n')[0].slice(0, 60)}` : `Page ${i + 1}`, page: i + 1, text: t });
      }
    });
  } else {
    // Markdown knowledge-base document: one passage per "## " section (split further if long).
    meta = { mode: 'index' };
    const body = clean(d.text);
    const docTitle = (body.match(/^# (.+)$/m) || [, d.title])[1].trim();
    const sections = body.split(/^## /m).slice(1);
    for (const s of sections) {
      const nl = s.indexOf('\n');
      const heading = s.slice(0, nl).trim();
      for (const t of pieces(s.slice(nl + 1))) {
        passages.push({ kb: d.kb, docId: d.docId, title: docTitle, section: heading, text: t });
      }
    }
  }
}

const truncated = meta.mode === 'upload' && passages.length > MAX_UPLOAD_PASSAGES;
const list = meta.mode === 'upload' ? passages.slice(0, MAX_UPLOAD_PASSAGES) : passages;
list.forEach((p, i) => { p.id = `${p.docId}#${i + 1}`; });

const batches = [];
for (let i = 0; i < list.length; i += BATCH) {
  const chunk = list.slice(i, i + BATCH);
  batches.push({
    json: {
      ...meta,
      truncated,
      passages: chunk,
      body: {
        requests: chunk.map((p) => ({
          model: MODEL,
          taskType: 'RETRIEVAL_DOCUMENT',
          title: `${p.title} - ${p.section}`,
          outputDimensionality: DIMS,
          content: { parts: [{ text: `${p.title} - ${p.section}\n${p.text}` }] },
        })),
      },
    },
  });
}
// Always return at least one item so the flow can report "no text found".
if (!batches.length) batches.push({ json: { ...meta, truncated: false, passages: [], body: { requests: [] }, empty: true } });
return batches;

// Code node: "Save Knowledge Base Vectors" (Run Once for All Items)
// Pairs each batch from "Split into Passages" with its Gemini embeddings and stores them in workflow static data.
const store = $getWorkflowStaticData('global');
const src = $('Split KB into Passages').all();
const res = $input.all();

const norm = (v) => {
  const n = Math.sqrt(v.reduce((s, x) => s + x * x, 0)) || 1;
  return v.map((x) => Math.round((x / n) * 10000) / 10000);
};

const passages = [];
const errors = [];
res.forEach((r, i) => {
  const emb = r.json.embeddings;
  const batch = src[i].json.passages;
  if (!Array.isArray(emb) || emb.length !== batch.length) {
    errors.push(r.json.error?.message || r.json.error || `batch ${i + 1}: no embeddings returned`);
    return;
  }
  batch.forEach((p, j) => passages.push({ ...p, vec: norm(emb[j].values) }));
});

if (errors.length) {
  return [{ json: { ok: false, message: 'Indexing failed, the old index was kept.', errors } }];
}

store.kb = passages;
store.indexedAt = new Date().toISOString();
const byKb = passages.reduce((a, p) => ((a[p.kb] = (a[p.kb] || 0) + 1), a), {});
return [{ json: { ok: true, indexedAt: store.indexedAt, passages: passages.length, byKb, documents: [...new Set(passages.map((p) => `${p.kb}: ${p.title}`))] } }];

// Code node: "Prepare Upload" (Run Once for All Items)
// Moves the uploaded file to the "data" binary field and gives the document a private token.
const item = $input.first();
const bin = item.binary || {};
const key = Object.keys(bin)[0];
const token = Array.from({ length: 24 }, () => 'abcdefghijklmnopqrstuvwxyz0123456789'[Math.floor(Math.random() * 36)]).join('');
if (!key) {
  return [{ json: { token, name: 'No file', noFile: true } }];
}
const name = String(bin[key].fileName || 'document.pdf').replace(/\.pdf$/i, '').replace(/[-_]+/g, ' ').trim();
return [{ json: { token, name }, binary: { data: bin[key] } }];

// Code node: "Collect PDF Pages" (Run Once for All Items)
// Normalises the Extract from File output into { kb:'doc', token, name, pages:[...] }.
const prep = $('Prepare Upload').first().json;
const j = $input.first().json;
let pages = [];
if (Array.isArray(j.text)) pages = j.text;
else if (typeof j.text === 'string') pages = j.text.split('\f');
pages = pages.map((p) => String(p || ''));
// Remove running headers and footers: lines that repeat on most pages (page numbers ignored).
if (pages.length >= 2) {
  const key = (l) => l.trim().replace(/\d+/g, '#');
  const seen = {};
  pages.forEach((p) => new Set(p.split('\n').map(key).filter(Boolean)).forEach((k) => (seen[k] = (seen[k] || 0) + 1)));
  const min = Math.max(2, Math.ceil(pages.length * 0.6));
  pages = pages.map((p) => p.split('\n').filter((l) => !(seen[key(l)] >= min)).join('\n'));
}
return [{ json: { kb: 'doc', token: prep.token, name: prep.name, pageCount: j.numpages || pages.length, pages } }];

// Code node: split documents into passages and build Gemini embedding batches (Run Once for All Items)
// Input items: { kb, docId, title, text } for knowledge-base docs, or { kb:'doc', token, name, pages:[...] } for uploads.
const MODEL = 'models/gemini-embedding-001';
const DIMS = 768;
const MAX_CHARS = 1000;
const MAX_CHARS_PDF = 700;
const MAX_UPLOAD_PASSAGES = 60;
const BATCH = 90;

