        })),
      },
    },
  });
}
// Always return at least one item so the flow can report "no text found".
if (!batches.length) batches.push({ json: { ...meta, truncated: false, passages: [], body: { requests: [] }, empty: true } });
return batches;

// Code node: "Save Uploaded Document" (Run Once for All Items)
const BASE_URL = 'https://n8n.rixgpt.com';
const KEEP_HOURS = 24;
const MAX_DOCS = 5;
const store = $getWorkflowStaticData('global');
store.docs = store.docs || {};
const src = $('Split PDF into Passages').all();
const res = $input.all();
const first = src[0].json;

const norm = (v) => {
  const n = Math.sqrt(v.reduce((s, x) => s + x * x, 0)) || 1;
  return v.map((x) => Math.round((x / n) * 10000) / 10000);
};

const passages = [];
let error = '';
if (first.empty) error = 'No readable text was found in this PDF. It may be a scanned image; try a PDF with selectable text.';
res.forEach((r, i) => {
  if (error) return;
  const emb = r.json.embeddings;
  const batch = src[i].json.passages;
  if (!Array.isArray(emb) || emb.length !== batch.length) {
    error = 'The document could not be indexed right now (the AI service may be busy). Please try again in a minute.';
    return;
  }
  batch.forEach((p, j) => passages.push({ ...p, vec: norm(emb[j].values) }));
});

// Remove expired uploads and keep only the newest MAX_DOCS.
const now = Date.now();
for (const [k, d] of Object.entries(store.docs)) {
  if (now - Date.parse(d.createdAt) > KEEP_HOURS * 3600e3) delete store.docs[k];
}
const keys = Object.keys(store.docs).sort((a, b) => Date.parse(store.docs[b].createdAt) - Date.parse(store.docs[a].createdAt));
for (const k of keys.slice(MAX_DOCS - 1)) delete store.docs[k];

store.docs[first.token] = {
  name: first.name,
  pageCount: first.pageCount,
  truncated: !!first.truncated,
  error,
  createdAt: new Date().toISOString(),
  passages,
};

return [{ json: { token: first.token, name: first.name, passages: passages.length, error, chatUrl: `${BASE_URL}/webhook/rag-chat?kb=doc&d=${first.token}` } }];

// Code node: "Build Chat Page" (Run Once for All Items)
const store = $getWorkflowStaticData('global');
const q = $input.first().json.query || {};
const kb = ['client', 'staff', 'doc'].includes(q.kb) ? q.kb : 'client';
const d = String(q.d || '').replace(/[^a-z0-9]/g, '').slice(0, 40);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// Drop expired uploads (older than 24 hours).
store.docs = store.docs || {};
for (const [k, v] of Object.entries(store.docs)) if (Date.now() - Date.parse(v.createdAt) > 24 * 3600e3) delete store.docs[k];

const kbDocs = (name) => {
  const ps = (store.kb || []).filter((p) => p.kb === name);
  return { titles: [...new Set(ps.map((p) => p.title))], passages: ps.length };
};
const doc = kb === 'doc' && d ? store.docs[d] : null;

const cfg = {
  kb, d,
  suggestions: {
    client: ['How much does a RAG chatbot cost?', 'What are your payment terms?', 'Do I own the code at the end?', 'How long does an n8n automation take?', 'I want to automate my invoices. How do I start?'],
    staff: ['How many annual leave days do I get?', 'How much notice do I need for 3 days off?', 'Can we deploy to production on a Friday?', 'What is the learning budget?', 'How do I request work from home?'],
    doc: ['Summarise this document', 'What are the key dates or deadlines?', 'What are the main obligations of each party?'],
  }[kb],
  welcome: {
    client: "Hi! I'm Harborline Software's assistant. Ask me about our services, prices, process or policies. I answer only from our published documents and show my sources.",
    staff: "Hi! I'm the team assistant. Ask me about leave, working hours, expenses, onboarding or engineering procedures. I answer only from the company handbook and show my sources.",
    doc: doc && !doc.error ? `Your document "${doc.name}" is ready (${doc.passages.length} passages indexed). Ask me anything about it.` : '',
  }[kb],
};

let info = '';
if (kb === 'doc') {
  if (!d || !doc) {
    info = `<div class="upload"><h2>${d ? 'This document has expired' : 'Chat with your own PDF'}</h2><p>Upload a PDF (text-based, up to about 30 pages). It is split into passages, indexed with Gemini embeddings and opened here so you can ask questions about it. Uploads are deleted automatically after 24 hours.</p><a class="btn" href="/form/rag-upload">Upload a PDF</a></div>`;
  } else if (doc.error) {
    info = `<div class="upload"><h2>We couldn't index "${esc(doc.name)}"</h2><p>${esc(doc.error)}</p><a class="btn" href="/form/rag-upload">Try another PDF</a></div>`;
  } else {
    info = `<div class="kbinfo"><span class="dot"></span>Answering from <b>${esc(doc.name)}</b> · ${doc.pageCount || '?'} pages · ${doc.passages.length} passages${doc.truncated ? ' (first part of the document only)' : ''} · <a href="/form/rag-upload">upload another</a></div>`;
  }
