function md(t){
  const lines=esc(t).split(/\\n/);let h='',inList=false;
  for(let l of lines){
    l=l.replace(/\\*\\*(.+?)\\*\\*/g,'<b>$1</b>').replace(/\\[(\\d+)\\]/g,'<sup class="c" data-n="$1">$1</sup>');
    const m=l.match(/^\\s*(?:[-*•]|\\d+\\.)\\s+(.*)/);
