    if(inList){h+='</ul>';inList=false}
    if(l.trim())h+='<p>'+l+'</p>';
  }
  if(inList)h+='</ul>';return h;
}
function add(role,html){const d=document.createElement('div');d.className='msg '+role;d.innerHTML='<div class="bubble">'+html+'</div>';log.appendChild(d);main.scrollTop=main.scrollHeight;return d}
function welcome(){
  if(!CFG.welcome)return;
  const m=add('bot','<p>'+esc(CFG.welcome)+'</p><div class="chips">'+CFG.suggestions.map(s=>'<button type="button" class="chip">'+esc(s)+'</button>').join('')+'</div>');
  m.querySelectorAll('.chip').forEach(c=>c.onclick=()=>ask(c.textContent));
}
function sourcesHtml(src){
  if(!src||!src.length)return '';
  return '<details class="src"><summary>Sources ('+src.length+')</summary><ol>'+src.map(s=>'<li id="s'+s.n+'"><span class="score">'+(s.score!=null?'match '+Math.round(s.score*100)+'%':'')+'</span><b>['+s.n+']</b> '+esc(s.title)+' › '+esc(s.section)+'<div class="snip">'+esc(s.text.length>420?s.text.slice(0,420)+'…':s.text)+'</div></li>').join('')+'</ol></details>';
}
async function ask(q){
  q=(q||'').trim();if(!q)return;
  const inp=document.getElementById('q'),btn=document.getElementById('b');
  inp.value='';btn.disabled=true;
  add('user','<p>'+esc(q)+'</p>');
  const t=add('bot','<div class="typing"><span></span><span></span><span></span></div>');
  let data;
  try{
    const r=await fetch('/webhook/rag-ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kb:CFG.kb,d:CFG.d,q,history:chatHistory})});
    data=await r.json();
  }catch(e){data={ok:false,answer:'Sorry, something went wrong. Please try again.'}}
  let h=md(data.answer||'');
  if(data.actions&&data.actions.includes('start_project'))h+='<a class="act" href="/form/project-inquiry" target="_blank">Start your project →</a>';
  if(data.actions&&data.actions.includes('leave_form'))h+='<a class="act" href="/form/leave-request" target="_blank">Open the leave request form →</a>';
  h+=sourcesHtml(data.sources);
  t.querySelector('.bubble').innerHTML=h;
  t.querySelectorAll('sup.c').forEach(s=>s.onclick=()=>{const d=t.querySelector('details');if(d){d.open=true;const li=t.querySelector('#s'+s.dataset.n);li&&li.scrollIntoView({block:'nearest',behavior:'smooth'})}});
  main.scrollTop=main.scrollHeight;
  if(data.ok){chatHistory.push({role:"user",text:q},{role:"assistant",text:data.answer});while(chatHistory.length>6)chatHistory.shift()}
  btn.disabled=false;inp.focus();
}
const f=document.getElementById('f');
if(f)f.onsubmit=e=>{e.preventDefault();ask(document.getElementById('q').value)};
welcome();
</script></body></html>`;

